import type {EvalCase,NoMatchWhy} from './cases';

// Held-out evaluation lines (BOXT task B3b): every probe line the B3 verifiers wrote in rounds 2 to 6
// that src/eval/cases.ts did not already hold, with their ground truth. The matcher was not tuned on
// them before they were added; src/eval/README.md records how they fared before and after the
// total-accounting change. Round 1's probes were added to cases.ts earlier (n47 to n76).
//
//   - heldMatch: the verifier's realistic must-match lines (b3v-must.txt, mm.json), and the four
//     labelled bag lines of nmm.json (L01 to L04), which name the right bag once W x L is read the way
//     bags are listed. h2n87 is one of those too: the verifier wrote it as must-not-match because the
//     old scorer read 9" W x 6" L as 6x9; BOXT sells the 9x6 4 mil bag.
//   - heldNoMatch: the must-not-match lines (b3v-mustnot.txt, b3v-more.txt, nmm.json). Each must
//     stay No match at Strict with either judge; Balanced and Lenient are reported, not guaranteed.
//   - HELDOUT_BARE_SIZES: round 2's 710 bare sizes (b3v-sizes.txt). They name no product, so they are
//     checked apart (eval.test.ts: no match at any level with either judge) rather than as cases.
// Generated from the verifiers' files; lines that repeat a cases.ts line (or each other) are left out.

const heldMatch=(id:string,line:string,sku:string,note:string):EvalCase=>({id,original:line,description:line,expect:{sku},note,tags:['heldout']});
const heldNoMatch=(id:string,line:string,why:NoMatchWhy,note:string):EvalCase=>({id,original:line,description:line,expect:'no_match',why,level:'strict',note,tags:['heldout']});

